import pandas as pd
import os
from dotenv import load_dotenv

import sys
# Add the parent directory (root) to sys.path so we can import app.py
sys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from app import get_eval_chain # Importing app.py existing logic of building the RAG chain and retriever
from deepeval.metrics import FaithfulnessMetric, AnswerRelevancyMetric
from deepeval.test_case import LLMTestCase

def run_evaluation():
    load_dotenv()
    
    # Load the synthetic dataset generated by generate_synthetic_data_deepeval.py
    df = pd.read_csv("evals/synthetic_eval_dataset.csv")
    
    # Initialize your RAG components using the same logic as in app.py
    pdf_path = ["docs/canadian bill of rights.pdf"]
    chain, retriever = get_eval_chain(pdf_path)
    
    results = []

    print(f"Starting evaluation on {len(df)} test cases...")

    for index, row in df.iterrows():
        question = row['input']
        expected_output = row['expected_output']
        
        # Run the RAG chain to get the actual output for the question
        # Use a unique session_id per question to keep history clean and avoid cross-contamination of contexts
        config = {"configurable": {"session_id": f"eval_{index}"}}
        actual_output = chain.invoke({"input": question}, config=config)
        
        # Get the retrieval context (the chunks found by FAISS) 
        retrieved_docs = retriever.invoke(question)
        retrieval_context = [doc.page_content for doc in retrieved_docs]
        
        # Create a DeepEval Test Case with the question, actual output, expected output, and retrieval context
        test_case = LLMTestCase(
            input=question,
            actual_output=actual_output,
            expected_output=expected_output,
            retrieval_context=retrieval_context
        )
        
        # Defined Metrics
        # Faithfulness: Did the LLM hallucinate or stick to the context?
        # Relevancy: Did the LLM actually answer the question asked?
        f_metric = FaithfulnessMetric(threshold=0.7)
        r_metric = AnswerRelevancyMetric(threshold=0.7)
        
        f_metric.measure(test_case)
        r_metric.measure(test_case)
        
        results.append({
            "input": question,
            "actual_output": actual_output,
            "expected_output": expected_output,
            "faithfulness_score": f_metric.score,
            "relevancy_score": r_metric.score,
            "reasoning": f_metric.reason
        })
        print(f"✅ Evaluated case {index + 1}/{len(df)}")

    # Export results to a new CSV for analysis
    results_df = pd.DataFrame(results)
    results_df.to_csv("evals/deepeval_results.csv", index=False)
    print("📊 Evaluation complete! Results saved to evals/deepeval_results.csv")

if __name__ == "__main__":
    run_evaluation()